SELECT ecr.stat_date as 'statDate', ecr.stat_date_str as statDateStr, SUM(IF(`instrument_type`='electricity_meter',total_cost ,0)) as 'electricityCost', SUM(IF(`instrument_type`='water_meter',total_cost,0)) as 'waterCost', SUM(IF(`instrument_type`='gas_meter',total_cost,0)) as 'gasCost' FROM energy_charge_report ecr
ecr.stat_date between #{param.period.begin} and #{param.period.end}
GROUP BY ecr.stat_date order by ecr.stat_date desc

SELECT ecr.stat_date AS statDate, ecr.stat_date_str AS statDateStr, SUM( CASE WHEN instrument_type = 'electricity_meter' THEN total_cost ELSE 0 END ) AS electricityCost, SUM( CASE WHEN instrument_type = 'water_meter' THEN total_cost ELSE 0 END ) AS waterCost, SUM( CASE WHEN instrument_type = 'gas_meter' THEN total_cost ELSE 0 END ) AS gasCost FROM energy_charge_report ecr
ecr.stat_date BETWEEN #{param.period.begin} AND #{param.period.end}
GROUP BY ecr.stat_date ORDER BY ecr.stat_date DESC

